/* external file style.css */
body   { font-family: Arial, sans-serif; color: #333; }
#menu  { background: hsl(210, 60%, 40%); }   /* id selector */
.note  { font-weight: bold; font-style: italic; }
ul.toc { list-style: square inside; }        /* shorthand */
a:hover { text-decoration: underline; }

console.log(typeof null);
console.log(typeof undefined, typeof NaN);
console.log(2 + "3", "6" - 2, "3" * "4");
console.log(1 == "1", 1 === "1");
console.log(null == undefined, null === undefined);
let a = [10, 20, 30];
console.log(a.map(x => x / 10).join("-"));
console.log(x);   // var is hoisted, value not yet assigned
var x = 5;
